ALTER TABLE public.rental_inquiries ADD COLUMN IF NOT EXISTS payment_decision_version integer NOT NULL DEFAULT 0;
CREATE OR REPLACE FUNCTION public.select_rental_payment_method(_id uuid, _offer text, _expected integer, _method text, _payload jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
DECLARE r public.rental_inquiries; item_net numeric; addon_net numeric; cost_net numeric; item_vat numeric; net numeric; vat numeric; gross numeric; eligible numeric; rebate numeric; actual_rebate numeric;
BEGIN
IF auth.role() IS DISTINCT FROM 'service_role' THEN RAISE EXCEPTION 'Not authorized' USING ERRCODE='42501'; END IF;
SELECT * INTO r FROM public.rental_inquiries WHERE id=_id FOR UPDATE;
IF NOT FOUND OR r.offer_number IS DISTINCT FROM _offer OR r.payment_decision_version<>_expected THEN RAISE EXCEPTION 'Auftrag wurde inzwischen geändert' USING ERRCODE='40001'; END IF;
IF _method NOT IN ('bank','regular') OR r.offer_payload->'bank_transfer_discount'->>'version' IS DISTINCT FROM 'bank-transfer-3-v1' OR (r.offer_payload->'bank_transfer_discount'->>'rate')::numeric IS DISTINCT FROM 3 THEN RAISE EXCEPTION 'Kein vereinbarter Überweisungsrabatt'; END IF;
IF EXISTS(SELECT 1 FROM public.deposit_settlements WHERE rental_inquiry_id=_id) THEN RAISE EXCEPTION 'Kaution bereits abgerechnet'; END IF;
IF _method IS DISTINCT FROM r.offer_payload->'bank_transfer_discount'->>'selected' AND EXISTS(SELECT 1 FROM public.inquiry_invoices WHERE rental_inquiry_id=_id AND status NOT IN ('draft','cancelled')) THEN RAISE EXCEPTION 'Zahlungswechsel benötigt zuerst Belegkorrektur'; END IF;
IF _method='bank' AND EXISTS(SELECT 1 FROM jsonb_array_elements(COALESCE(r.payments,'[]')) p WHERE (p->>'amount')::numeric>0 AND (p->>'label' IS DISTINCT FROM 'Banküberweisung' OR p->>'provider'='stripe' OR COALESCE(p->>'reference','')~'^(cs_|pi_)')) THEN RAISE EXCEPTION 'Gemischte Zahlungen erhalten keinen Überweisungsrabatt'; END IF;
IF EXISTS(SELECT 1 FROM public.offer_payment_links WHERE inquiry_table='rental_inquiries' AND inquiry_id=_id AND status='active' AND stripe_session_id IS NOT NULL) THEN RAISE EXCEPTION 'Online-Zahlung muss zuerst sicher beendet werden'; END IF;
SELECT COALESCE(sum(round((i->>'quantity')::numeric*(i->>'unit_price')::numeric*(1-COALESCE((i->>'discount_percent')::numeric,0)/100),2)),0),round(COALESCE(sum(round((i->>'quantity')::numeric*(i->>'unit_price')::numeric*(1-COALESCE((i->>'discount_percent')::numeric,0)/100),2)*COALESCE((i->>'vat_rate')::numeric,19)/100),0),2) INTO item_net,item_vat FROM jsonb_array_elements(_payload->'items') i;
SELECT round(COALESCE(sum((a->>'amount')::numeric),0),2),round(COALESCE(sum(CASE WHEN a->>'key'='bank_transfer_discount_v1' THEN -(a->>'amount')::numeric ELSE 0 END),0),2) INTO addon_net,actual_rebate FROM jsonb_array_elements(_payload->'items') i CROSS JOIN LATERAL jsonb_array_elements(COALESCE(i->'addons','[]')) a WHERE COALESCE((a->>'optional')::boolean,false)=false;
cost_net:=COALESCE((_payload->>'delivery_cost_delivery')::numeric,0)+COALESCE((_payload->>'delivery_cost_return')::numeric,0)+COALESCE((_payload->>'setup_cost')::numeric,0)+COALESCE((_payload->>'dismantle_cost')::numeric,0)+COALESCE((_payload->>'return_location_cost')::numeric,0);
SELECT COALESCE(sum(GREATEST(0,round((i->>'quantity')::numeric*(i->>'unit_price')::numeric*(1-COALESCE((i->>'discount_percent')::numeric,0)/100),2)) + COALESCE((SELECT sum((a->>'amount')::numeric) FROM jsonb_array_elements(COALESCE(i->'addons','[]')) a WHERE a->>'key'<>'bank_transfer_discount_v1' AND COALESCE((a->>'optional')::boolean,false)=false AND COALESCE(a->>'payment_cost_kind','rental')='rental'),0)),0)+cost_net INTO eligible FROM jsonb_array_elements(_payload->'items') i WHERE COALESCE((i->>'vat_rate')::numeric,19)<>0 AND COALESCE(i->>'payment_cost_kind','rental')='rental';
rebate:=CASE WHEN _method='bank' THEN round(GREATEST(0,eligible)*0.03,2) ELSE 0 END;
IF actual_rebate IS DISTINCT FROM rebate THEN RAISE EXCEPTION 'Rabattberechnung stimmt nicht'; END IF;
net:=round(item_net+addon_net+cost_net,2); vat:=round(item_vat+addon_net*0.19+cost_net*0.19,2); gross:=net+vat;
IF net IS DISTINCT FROM (_payload->'totals'->>'netAmount')::numeric OR vat IS DISTINCT FROM (_payload->'totals'->>'vatAmount')::numeric OR gross IS DISTINCT FROM (_payload->'totals'->>'grossAmount')::numeric OR (_payload->'bank_transfer_discount'->>'selected') IS DISTINCT FROM _method THEN RAISE EXCEPTION 'Zahlbetrag stimmt nicht mit Positionen überein'; END IF;
IF (r.offer_payload - 'items' - 'totals' - 'bank_transfer_discount') IS DISTINCT FROM (_payload - 'items' - 'totals' - 'bank_transfer_discount') THEN RAISE EXCEPTION 'Zahlungsentscheidung darf Auftragsdaten nicht ändern'; END IF;
UPDATE public.rental_inquiries SET original_accepted_offer=CASE WHEN status='accepted' THEN COALESCE(original_accepted_offer,jsonb_build_object('offer_payload',offer_payload,'offer_total_gross',offer_total_gross,'offer_number',offer_number,'offer_file_url',offer_file_url)) ELSE original_accepted_offer END, offer_payload=_payload,offer_total_gross=gross,payment_decision_version=payment_decision_version+1 WHERE id=_id;
UPDATE public.sign_bookings SET gross_cents=round(gross*100)::integer,total_cents=round(gross*100)::integer+deposit_cents,snapshot=jsonb_set(snapshot,'{offer_payload}',_payload) WHERE inquiry_id=_id AND status='reserved';
INSERT INTO public.rental_inquiry_events(rental_inquiry_id,event,details) VALUES(_id,'payment_method_selected',jsonb_build_object('method',_method,'discount_net',rebate,'gross',gross,'version',_expected+1));
RETURN jsonb_build_object('version',_expected+1,'gross',gross);
END; $$;
REVOKE ALL ON FUNCTION public.select_rental_payment_method(uuid,text,integer,text,jsonb) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.select_rental_payment_method(uuid,text,integer,text,jsonb) TO service_role;
CREATE OR REPLACE FUNCTION public.guard_bank_discount_payments() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN
IF NEW.offer_payload->'bank_transfer_discount'->>'selected'='bank' AND EXISTS(SELECT 1 FROM jsonb_array_elements(COALESCE(NEW.payments,'[]')) p WHERE (p->>'amount')::numeric>0 AND (p->>'label' IS DISTINCT FROM 'Banküberweisung' OR p->>'provider'='stripe' OR COALESCE(p->>'reference','')~'^(cs_|pi_)')) THEN RAISE EXCEPTION 'Überweisungsrabatt: vor Erfassung anderer Zahlungsarten Zahlungsart wechseln; ggf. Belegkorrektur erforderlich'; END IF;
RETURN NEW; END; $$;
CREATE TRIGGER bank_discount_payments_guard BEFORE INSERT OR UPDATE OF payments,offer_payload ON public.rental_inquiries FOR EACH ROW EXECUTE FUNCTION public.guard_bank_discount_payments();
REVOKE ALL ON FUNCTION public.guard_bank_discount_payments() FROM PUBLIC,anon,authenticated;